#include "BluetoothA2DPSink.h"
#include <Adafruit_GFX.h>    
#include <Adafruit_ST7735.h> 
#include <SPI.h>
#include <ESP32Encoder.h>

// Настройки дисплея SPI (ST7735 0.96")
#define TFT_CS     5
#define TFT_RST    4
#define TFT_DC     2
Adafruit_ST7735 tft = Adafruit_ST7735(TFT_CS, TFT_DC, TFT_RST);

// Настройки энкодера
#define ENC_CLK    14
#define ENC_DT     12
#define ENC_SW     13
ESP32Encoder encoder;
int64_t oldEncoderValue = 0;
unsigned long lastButtonPress = 0;

// Инициализация Bluetooth A2DP
BluetoothA2DPSink a2dp_sink;
int current_volume = 30; // Начальная громкость (0-127)
String track_title = "Ready for BT...";

// Функция обновления информации на экране
void updateDisplay() {
    tft.fillScreen(ST7735_BLACK);
    tft.setCursor(0, 10);
    tft.setTextColor(ST7735_CYAN);
    tft.setTextSize(1);
    tft.println("   ESP32 PLAYER   ");
    tft.println("--------------------");

    // Статус / Трек
    tft.setTextColor(ST7735_WHITE);
    tft.setCursor(0, 40);
    tft.setTextSize(1);
    tft.println("Track:");
    tft.setTextColor(ST7735_YELLOW);
    tft.println(track_title.substring(0, 30)); // Ограничение длины строки

    // Громкость
    tft.setTextColor(ST7735_GREEN);
    tft.setCursor(0, 90);
    tft.print("Volume: ");
    tft.print(map(current_volume, 0, 127, 0, 100)); // перевод в 0-100%
    tft.println("%");
}

// Коллбек получения метаданных (название трека)
void avrc_metadata_callback(uint8_t id, const uint8_t *text) {
    if (id == ESP_AVRC_MD_ATTR_TITLE) {
        track_title = String((char*)text);
        updateDisplay();
    }
}

void setup() {
    Serial.begin(115200);

    // Инициализация дисплея (для ST7735S 0.96" часто подходит INITR_MINI160x80)
    tft.initR(INITR_MINI160x80); 
    tft.setRotation(1); // Альбомный режим
    updateDisplay();

    // Инициализация энкодера
    ESP32Encoder::useInternalWeakPullResistures = gpio_pull_mode_t::GPIO_PULLUP_ONLY;
    encoder.attachHalfQuad(ENC_CLK, ENC_DT);
    encoder.setCount(current_volume);
    pinMode(ENC_SW, INPUT_PULLUP);

    // Настройка I2S выводов для PCM5102A
    i2s_pin_config_t my_pin_config = {
        .bck_io_num = 26,
        .ws_io_num = 25,
        .data_out_num = 22,
        .data_in_num = I2S_PIN_NO_CHANGE
    };
    a2dp_sink.set_pin_config(my_pin_config);

    // Подключение коллбека метаданных и запуск Bluetooth
    a2dp_sink.set_avrc_metadata_callback(avrc_metadata_callback);
    a2dp_sink.start("ESP32_Audio_Sink");
    a2dp_sink.set_volume(current_volume);
}

void loop() {
    // 1. Обработка вращения энкодера (Громкость)
    int64_t newEncoderValue = encoder.getCount();
    if (newEncoderValue != oldEncoderValue) {
        // Ограничиваем громкость в пределах 0 - 127 (стандарт для BT A2DP)
        if (newEncoderValue < 0) { encoder.setCount(0); newEncoderValue = 0; }
        if (newEncoderValue > 127) { encoder.setCount(127); newEncoderValue = 127; }

        current_volume = newEncoderValue;
        a2dp_sink.set_volume(current_volume);
        oldEncoderValue = newEncoderValue;
        updateDisplay();
    }

    // 2. Обработка нажатия кнопки (Play / Pause)
    if (digitalRead(ENC_SW) == LOW) {
        if (millis() - lastButtonPress > 300) { // Дебаунс 300мс
            if (a2dp_sink.get_audio_state() == ESP_A2D_AUDIO_STATE_STARTED) {
                a2dp_sink.pause();
                track_title = "[ PAUSED ]";
            } else {
                a2dp_sink.play();
            }
            updateDisplay();
            lastButtonPress = millis();
        }
    }

    delay(10);
}
